CREATE TRIGGER record_capture_insert AFTER INSERT ON orgtree.agents REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_agents();

CREATE TRIGGER record_capture_update AFTER UPDATE ON orgtree.agents REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_agents();

CREATE TRIGGER record_capture_delete AFTER DELETE ON orgtree.agents REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_agents();

DROP TRIGGER IF EXISTS record_capture_insert ON orgtree.delivery_batches;

DROP TRIGGER IF EXISTS record_capture_update ON orgtree.delivery_batches;

DROP TRIGGER IF EXISTS record_capture_delete ON orgtree.delivery_batches;

CREATE OR REPLACE FUNCTION orgtree.record_capture_delivery_batches() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,orgtree AS $fn$
BEGIN
  IF current_setting('orgtree.capture', true) = 'off' THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'agent' AS entity, r.agent_id::text AS entity_id FROM new_rows r WHERE r.agent_id IS NOT NULL
        UNION ALL
        SELECT '~scope' AS entity, 'detail:' || (r.agent_id)::text AS entity_id FROM new_rows r WHERE true
        UNION ALL
        SELECT '~scope' AS entity, 'lineage:' || (r.agent_id)::text AS entity_id FROM new_rows r WHERE true
        UNION ALL
        SELECT 'agent_mail:'||r.agent_id AS entity, r.agent_id||'/pending:delivery:'||r.id||':'||generate_series(0,(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END)-1) AS entity_id FROM new_rows r WHERE true
        UNION ALL
        SELECT '~scope' AS entity, 'mail_owner:' || (r.agent_id)::text AS entity_id FROM new_rows r WHERE true
        UNION ALL
        SELECT '~scope' AS entity, 'mail_pending_size:' || (r.agent_id||':'||r.id||':'||(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END))::text AS entity_id FROM new_rows r WHERE true
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'agent' AS entity, r.agent_id::text AS entity_id FROM old_rows r WHERE (r.agent_id IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'detail:' || (r.agent_id)::text AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'lineage:' || (r.agent_id)::text AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT 'agent_mail:'||r.agent_id AS entity, r.agent_id||'/pending:delivery:'||r.id||':'||generate_series(0,(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END)-1) AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'mail_owner:' || (r.agent_id)::text AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'mail_pending_size:' || (r.agent_id||':'||r.id||':'||(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END))::text AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT 'agent' AS entity, r.agent_id::text AS entity_id FROM new_rows r WHERE (r.agent_id IS NOT NULL) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'detail:' || (r.agent_id)::text AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'lineage:' || (r.agent_id)::text AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT 'agent_mail:'||r.agent_id AS entity, r.agent_id||'/pending:delivery:'||r.id||':'||generate_series(0,(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END)-1) AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'mail_owner:' || (r.agent_id)::text AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT '~scope' AS entity, 'mail_pending_size:' || (r.agent_id||':'||r.id||':'||(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END))::text AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'agent' AS entity, r.agent_id::text AS entity_id FROM old_rows r WHERE r.agent_id IS NOT NULL
        UNION ALL
        SELECT '~scope' AS entity, 'detail:' || (r.agent_id)::text AS entity_id FROM old_rows r WHERE true
        UNION ALL
        SELECT '~scope' AS entity, 'lineage:' || (r.agent_id)::text AS entity_id FROM old_rows r WHERE true
        UNION ALL
        SELECT 'agent_mail:'||r.agent_id AS entity, r.agent_id||'/pending:delivery:'||r.id||':'||generate_series(0,(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END)-1) AS entity_id FROM old_rows r WHERE true
        UNION ALL
        SELECT '~scope' AS entity, 'mail_owner:' || (r.agent_id)::text AS entity_id FROM old_rows r WHERE true
        UNION ALL
        SELECT '~scope' AS entity, 'mail_pending_size:' || (r.agent_id||':'||r.id||':'||(CASE WHEN json_typeof(r.mail)='array' THEN json_array_length(r.mail) ELSE 0 END))::text AS entity_id FROM old_rows r WHERE true
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  END IF;
  PERFORM set_config('orgtree.pending_scopes', '1', true);
  RETURN NULL;
END
