CREATE OR REPLACE FUNCTION orgtree.record_capture_user_outbox_attachments() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,orgtree AS $fn$
BEGIN
  IF current_setting('orgtree.capture', true) = 'off' THEN RETURN NULL; END IF;
  IF TG_OP = 'INSERT' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'user_outbox:shared' AS entity, r.user_outbox_id::text AS entity_id FROM new_rows r WHERE true
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'user_outbox:shared' AS entity, r.user_outbox_id::text AS entity_id FROM old_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM new_rows p WHERE to_json(r)::text=to_json(p)::text)
        UNION ALL
        SELECT 'user_outbox:shared' AS entity, r.user_outbox_id::text AS entity_id FROM new_rows r WHERE (true) AND NOT EXISTS (SELECT 1 FROM old_rows p WHERE to_json(r)::text=to_json(p)::text)
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO orgtree.changes (xid, entity, entity_id)
      SELECT DISTINCT pg_current_xact_id(), entity, entity_id FROM (
        SELECT 'user_outbox:shared' AS entity, r.user_outbox_id::text AS entity_id FROM old_rows r WHERE true
      ) named WHERE entity IS NOT NULL AND entity_id IS NOT NULL
      ON CONFLICT DO NOTHING;
  END IF;
  RETURN NULL;
END
$fn$;

CREATE TRIGGER record_capture_insert AFTER INSERT ON orgtree.user_outbox_attachments REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_user_outbox_attachments();

CREATE TRIGGER record_capture_update AFTER UPDATE ON orgtree.user_outbox_attachments REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_user_outbox_attachments();

CREATE TRIGGER record_capture_delete AFTER DELETE ON orgtree.user_outbox_attachments REFERENCING OLD TABLE AS old_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_user_outbox_attachments();

DROP TRIGGER IF EXISTS record_capture_insert ON orgtree.user_outbox_attachments_missing;

DROP TRIGGER IF EXISTS record_capture_update ON orgtree.user_outbox_attachments_missing;

DROP TRIGGER IF EXISTS record_capture_delete ON orgtree.user_outbox_attachments_missing;

