CREATE TRIGGER record_capture_insert AFTER INSERT ON orgtree.user_outbox_attachments_missing REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION orgtree.record_capture_user_outbox_attachments_missing();

